from dataclasses import dataclass
from typing import ClassVar

@dataclass
class Empleado:
    nombre: str
    salario: float
    departamento: str
    _contador: ClassVar[int] = 0

    def __post_init__(self) -> None:
        Empleado._contador += 1

    @classmethod
    def total(cls) -> int:
        return cls._contador

ana = Empleado("Ana", 50000, "IT")
bob = Empleado("Bob", 60000, "HR")
print(Empleado.total())  # 2

from typing import Optional, Union

def buscar(items: list[str], objetivo: str) -> Optional[int]:
    """Retorna el índice o None si no existe."""
    try:
        return items.index(objetivo)
    except ValueError:
        return None

result = buscar(["a", "b", "c"], "b")
print(result)  # 1

from typing import TypeVar, Generic

T = TypeVar("T")

class Caja(Generic[T]):
    def __init__(self, contenido: T) -> None:
        self.contenido = contenido

    def obtener(self) -> T:
        return self.contenido

caja_int = Caja(42)
caja_str = Caja("hola")
print(caja_int.obtener())  # 42

from typing import overload

@overload
def procesar(x: int) -> str: ...
@overload
def procesar(x: str) -> int: ...

def procesar(x):
    if isinstance(x, int):
        return str(x)
    return int(x)

print(procesar(42))     # "42"
print(procesar("42"))   # 42

from typing import TypedDict

class UserDict(TypedDict):
    nombre: str
    edad: int
    email: str

def procesar_usuario(user: UserDict) -> str:
    return f"{user['nombre']} ({user['edad']}): {user['email']}"

usuario: UserDict = {"nombre": "Ana", "edad": 30, "email": "ana@ejemplo.com"}
print(procesar_usuario(usuario))

