### Solution:
```swift
import Foundation

class WebBrowser {
    private var history: [String] = []
    private var currentIndex: Int = -1

    func visit(url: String) {
        if currentIndex < history.count - 1 {
            history = Array(history[0...currentIndex])
        }
        history.append(url)
        currentIndex += 1
    }

    func goBack() -> String? {
        guard currentIndex > 0 else {
            return nil
        }
        currentIndex -= 1
        return history[currentIndex]
    }

    func goForward() -> String? {
        guard currentIndex < history.count - 1 else {
            return nil
        }
        currentIndex += 1
        return history[currentIndex]
    }
}

