- (Dict[str, int]): A dictionary containing the minimum amount of each input chemical required to produce the specified quantity of FUEL. The keys are the chemical symbols, and the values are the quantities needed.

Note:
- You can assume that there will always be a valid set of conversion rules to produce the specified quantity of FUEL.

Example:
```python
rules = ["1 A, 3 B => 1 C", "5 C, 2 B => 1 FUEL"]
fuel_quantity = 1
output = min_input_chemicals(rules, fuel_quantity)
print(output)  # Output: {'A': 5, 'B': 7}
```

### Solution:
```python
from typing import List, Dict

def parse_rule(rule: str) -> (Dict[str, int], str, int):
    inputs, output = rule.split(" => ")
    input_chemicals = {}
    for input_chemical in inputs.split(", "):
        quantity, chemical = input_chemical.split()
        input_chemicals[chemical] = int(quantity)
    output_quantity, output_chemical = output.split()
    return input_chemicals, output_chemical, int(output_quantity)

def min_input_chemicals(rules: List[str], fuel_quantity: int) -> Dict[str, int]:
    reactions = {}
    for rule in rules:
        inputs, output_chemical, output_quantity = parse_rule(rule)
        reactions[output_chemical] = (output_quantity, inputs)

    def calculate_requirements(chemical: str, quantity: int, reactions: Dict[str, (int, Dict[str, int])]) -> Dict[str, int]:
        if chemical == "ORE":
            return {"ORE": quantity}
        output_quantity, inputs = reactions[chemical]
        multiplier = -(-quantity // output_quantity)  # Equivalent to ceil division
        requirements = {}
        for input_chemical, input_quantity in inputs.items():
            requirements[input_chemical] = input_quantity * multiplier
        excess = output_quantity * multiplier - quantity
        if excess > 0:
            requirements[chemical] = excess
        total_requirements = {}
        for input_chemical, input_quantity in requirements.items():
            sub_requirements = calculate_requirements(input_chemical, input_quantity, reactions)
            for sub_chemical, sub_quantity in sub_requirements.items():
                total_requirements[sub_chemical] = total_requirements.get(sub_chemical, 0) + sub_quantity
        return total_requirements

    return calculate_requirements("FUEL", fuel_quantity, reactions)
```

