internal func _statxFile(atPath path: String) throws -> (stat, Date?) {
    if #available(macOS 10.15, *) {
        var statxInfo = try statxFile(atPath: path)
        let creationDate = Date(timeIntervalSince1970: TimeInterval(statxInfo.stx_btime.tv_sec))
        return (statxInfo, creationDate)
