        "id": 1,
        "name": "Node 1",
        "children": [
            {
                "id": 2,
                "name": "Node 2",
                "children": []
            },
            {
                "id": 3,
                "name": "Node 3",
                "children": [
                    {
                        "id": 4,
                        "name": "Node 4",
                        "children": []
                    }
                ]
            }
        ]
    }
]

selected_id = 3
result = filter_selected_node(tree, selected_id)
print(result)  # Output: [{'id': 3, 'name': 'Node 3', 'children': [{'id': 4, 'name': 'Node 4', 'children': []}]}]
```

