### Solution:
```python
import json
from typing import Union, List

def get_latest_supported_openshift_version(file_path: str) -> Union[str, List[str]]:
    with open(file_path, 'r') as file:
        data = json.load(file)
        supported_versions = [v['version'] for v in data['versions'] if v['supported']]
