from typing import TypeVar, Generic, Callable, Optional

T = TypeVar('T')
BaseUniverseType = TypeVar('BaseUniverseType', bound='Universe')

def is_cell(value: T) -> bool:
    """Checks if the value is a valid cell."""
    # Implementation not provided

class Universe(Generic[T]):
    def __init__(self, width: int, height: int):
        """Initializes the universe with the specified dimensions."""
        self.grid = [[None for _ in range(width)] for _ in range(height)]

    def through(self):
        """Generator to iterate through the universe."""
        for y in range(len(self.grid)):
            for x in range(len(self.grid[0])):
                yield x, y

    def __setitem__(self, key: tuple, value: Optional[T]):
        """Sets the value of a cell in the universe."""
        x, y = key
        self.grid[y][x] = value

    @classmethod
    def from_data(cls, data: list) -> BaseUniverseType:
        """Creates a universe from the given data."""
        universe = cls(len(data[0]), len(data))
        for y in range(len(data)):
            for x in range(len(data[0])):
                universe[x, y] = data[y][x] if is_cell(data[y][x]) else None
        return universe

    @classmethod
    def random(cls, width: int, height: int, get_random: Callable[[], T]) -> BaseUniverseType:
        """Creates a random universe of the specified dimensions."""
        universe = cls(width, height)
        for x, y in universe.through():
            universe[x, y] = get_random()
        return universe
```
