### Solution:
```python
from typing import Dict, Tuple
import constants  # Assuming constants module is available

class CommunicationInterface:
    def __init__(self):
        self.sessions: Dict[int, str] = {}

    def open_session(self, session_id: int) -> None:
        self.sessions[session_id] = ""

    def close_session(self, session_id: int) -> None:
        if session_id in self.sessions:
            del self.sessions[session_id]

    def read_message(self, session_id: int) -> str:
        if session_id in self.sessions:
            reply, status_code = self.visalib.read(self.sessions[session_id])
            return reply if status_code == constants.StatusCode.success else "Error reading message"
        else:
            return "Session not found"

    def write_message(self, session_id: int, message: str) -> Tuple[int, constants.StatusCode]:
        if session_id in self.sessions:
            self.visalib.write(self.sessions[session_id], message)
            return len(message), constants.StatusCode.success
        else:
            return 0, constants.StatusCode.failure
