### Solution:
```python
from typing import List, Dict, Union

def process_arguments(input_list: List[str]) -> Dict[str, Union[bool, str]]:
    args = {}
    current_flag = None
    for arg in input_list:
        if arg.startswith('-'):
            current_flag = arg
            args[current_flag] = []
        else:
            if current_flag:
                if len(args[current_flag]) == 0:
                    args[current_flag].append(True)
                args[current_flag][-1] = arg
            else:
                args[arg] = True
    for key, value in args.items():
        if isinstance(value, list) and len(value) == 1:
            args[key] = value[0]
    return args
