struct QueryPredicateOperation {
    let field: String
    let operation: String
    let value: Any

    func le(_ value: Persistable) -> QueryPredicateOperation {
        return QueryPredicateOperation(field: field, operation: " <= ", value: value.asQueryValue())
    }

