    let identifier: String
    let beacons: [Beacon]
}
```

For example, given a beacon region with identifier "Office" and beacons [(major: 1, minor: 2), (major: 2, minor: 1), (major: 1, minor: 3)], and a target beacon with major 1 and minor 1, the function should return the beacon with major 1 and minor 2 as it is the closest to the target beacon.

### Solution:
```swift
func findClosestBeacon(_ beaconRegion: BeaconRegion, _ targetBeacon: Beacon) -> Beacon? {
    var closestBeacon: Beacon?
    var minDistance = Int.max

    for beacon in beaconRegion.beacons {
        let distance = abs(beacon.major - targetBeacon.major) + abs(beacon.minor - targetBeacon.minor)
        if distance < minDistance {
            minDistance = distance
            closestBeacon = beacon
        } else if distance == minDistance {
            if beacon.major < closestBeacon!.major {
                closestBeacon = beacon
            } else if beacon.major == closestBeacon!.major && beacon.minor < closestBeacon!.minor {
                closestBeacon = beacon
            }
        }
    }

    return closestBeacon
}
```

