from typing import List, Dict, Union

class Token:
    MapStart = "MapStart"
    MapEnd = "MapEnd"
    String = "String"

def processTokens(tokens: List[Token]) -> Dict[str, Union[str, Dict[str, Union[str, Dict[str, Union[str, ...]]]]]]:
    stack = []
    current_map = {}
    stack.append(current_map)

    for token in tokens:
        if token == Token.MapStart:
            new_map = {}
            stack[-1][key] = new_map
            stack.append(new_map)
        elif token == Token.MapEnd:
            stack.pop()
        elif token == Token.String:
            key = token.value
            stack[-1][key] = None
        else:
            raise ValueError("Invalid token")

    return current_map
