    bank = Bank()

    @click.command()
    @click.option('--deposit', type=float, help='Deposit funds into the account')
    @click.option('--withdraw', type=float, help='Withdraw funds from the account')
    @click.option('--check_balance', is_flag=True, help='Check the account balance')
    def account_operations(deposit, withdraw, check_balance):
        account_number = bank.create_account(name, initial_balance)
        if deposit:
            click.echo(f"Updated balance: {bank.deposit(account_number, deposit)}")
        elif withdraw:
            result = bank.withdraw(account_number, withdraw)
            if isinstance(result, float):
                click.echo(f"Updated balance: {result}")
            else:
                click.echo(result)
        elif check_balance:
            result = bank.check_balance(account_number)
            if isinstance(result, float):
                click.echo(f"Current balance: {result}")
            else:
                click.echo(result)

    account_operations()

if __name__ == '__main__':
    cli()
```

