STATUS_COMPLETED = 'completed'

class MigrationController:
    def __init__(self, databases: List[str], groups: Dict[str, str]):
        self.databases = databases
        self.groups = groups
        self.migration_status = {group: {db: [] for db in databases} for group in groups}

