// Definition of the List enum
enum List {
    Cons(i32, Box<List>),
    Nil,
}

impl List {
    // Constructor for creating a new list node
    fn new(value: i32, next: List) -> List {
        List::Cons(value, Box::new(next))
    }

    // Method to convert the list into a string representation
    fn stringify(&self) -> String {
        match *self {
