public extension Validation {
    static func isEven(_ value: Int) -> Bool {
        return value % 2 == 0
    }

    static func isOdd(_ value: Int) -> Bool {
        return value % 2 != 0
    }

    static func isPrime(_ value: Int) -> Bool {
